    asm volatile("{.reg .pred q;mbarrier.try_wait.parity.shared::cta.b64 q,[%1],%2;selp.b32 %0,1,0,q;}"
                 : "=r"(ok) : "r"(su(p)), "r"(phase) : "memory");
  } while (!ok);
#if VQ8_CLK
  if ((threadIdx.x & 31) == 0) {
    unsigned long long* a = clk_area();
    const int w = threadIdx.x >> 5;
    a[w] += clock64() - c0;
    if (!a[12 + w]) a[12 + w] = gtime();
  }
#endif
}
