  for(int rh=0;rh<2;rh++) {
    const int row=w*16+g+8*rh;
    float den=ls[rh];den+=__shfl_xor_sync(0xffffffffu,den,1);den+=__shfl_xor_sync(0xffffffffu,den,2);
    float* pp=part+row*68;
