          if(idx<ne){if constexpr(Z)if(m==0&&i==0)ss[off+idx]=0.f;
            inter[(size_t)(off+idx)*HD+m*8+i]=__float2bfloat16(g0/(1.f+__expf(-g0))*u0);}
          if(idx+1<ne){if constexpr(Z)if(m==0&&i==0)ss[off+idx+1]=0.f;
            inter[(size_t)(off+idx+1)*HD+m*8+i]=__float2bfloat16(g1/(1.f+__expf(-g1))*u1);}
        }else{float scale=gs2[e]*256.f,p0=1.f+__bfloat162float(pnw[m*16+i]),p1=1.f+__bfloat162float(pnw[m*16+i+8]);
          float v0=a0*scale,v1=a1*scale,v2=a2*scale,v3=a3*scale;
          float z0=v0*p0,z1=v1*p0,z2=v2*p1,z3=v3*p1;
          if(idx<ne){y[(size_t)(off+idx)*HD+m*16+i]=ZOUT?z0:v0;y[(size_t)(off+idx)*HD+m*16+i+8]=ZOUT?z2:v2;}
          if(idx+1<ne){y[(size_t)(off+idx+1)*HD+m*16+i]=ZOUT?z1:v1;y[(size_t)(off+idx+1)*HD+m*16+i+8]=ZOUT?z3:v3;}
          float sq0=idx<ne?z0*z0+z2*z2:0.f,sq1=idx+1<ne?z1*z1+z3*z3:0.f;
          if constexpr(VNR){nv0+=sq0;nv1+=sq1;}else{
#pragma unroll
            for(int d=4;d<=16;d*=2){sq0+=__shfl_xor_sync(~0u,sq0,d);sq1+=__shfl_xor_sync(~0u,sq1,d);}
            if(lane<4){if(idx<ne)atomicAdd(ss+off+idx,sq0);if(idx+1<ne)atomicAdd(ss+off+idx+1,sq1);}
          }
        }
      }
    }else{
    if (pass == 0) {
      const float sc = gs13[e] * 256.f;
      if (tid < 8 * NB) {
        const int i = tid & 7, n = tid >> 3, j = n >> 3, col = n & 7;
        const int ls = i * 4 + (col >> 1), rg = j * 4 + (col & 1);
        float G1 = 0.f, U = 0.f;
#pragma unroll
        for (int w = 0; w < NCW; ++w) {
          G1 += rb[(w * 32 + ls) * RED + rg];
          U += rb[(w * 32 + ls) * RED + rg + 2];
        }
        const int idx = nb * NB + n;
        if (idx < ne) {
          if constexpr (Z) { if (m == 0 && i == 0) ss[off + idx] = 0.f; }
          G1 *= sc;
          U *= sc;
          const float h = G1 / (1.f + __expf(-G1)) * U;
          inter[static_cast<size_t>(off + idx) * HD + m * 8 + i] = __float2bfloat16(h);
        }
      }
    } else {
      const float sc = gs2[e] * 256.f;
      if (tid < 16 * NB) {
        const int i = tid & 15, n = tid >> 4, j = n >> 3, col = n & 7;
        const int ls = (i & 7) * 4 + (col >> 1), rg = j * 4 + (col & 1) + ((i >> 3) << 1);
        float v = 0.f;
#pragma unroll
        for (int w = 0; w < NCW; ++w) v += rb[(w * 32 + ls) * RED + rg];
        v *= sc;
        const int idx = nb * NB + n;
        const bool ok = idx < ne;
        const float z = v * fw[0];
        if (ok) y[static_cast<size_t>(off + idx) * HD + m * 16 + i] = ZOUT ? z : v;
        if constexpr (NREG) {
          if (ok) { nacc += z * z; npos = off + idx; }
        } else {
          float t2 = ok ? z * z : 0.f;
#pragma unroll
          for (int d = 8; d > 0; d >>= 1) t2 += __shfl_xor_sync(~0u, t2, d);   // 16 rows of one token
          if (ok && i == 0) atomicAdd(ss + off + idx, t2);
        }
      }
    }
    }
    if constexpr(TRACE)if(tid==0){probe[56+pass]+=tg()-et;probe[58+pass]++;}
    if constexpr (TRACE) {
      if (tid == 0 && pass == 0 && firstp) probe[13] = tg();
    }
    buf ^= 1;
    ++seg_tiles;
  };
  for (int pass = 0; pass < 2; ++pass) {
    const int ua = pass ? a2 : a1, ub = pass ? b2 : b1;
    const int* us = pass ? rt->us2 : rt->us1;
    const int cc = pass ? rt->c2 : rt->c1;
    const int ntile = pass ? NT2 : NT1;
    int e = 0, nb = 0, m = 0, mb = 0, me = 0;
    if constexpr (!SLOT) {
      if (ua < ub) {
        decode_unit(ua, us, rt->nblk, cc, ntile, e, nb, m);
        mb = (m / cc) * cc;
        me = min(ntile, mb + cc);
      }
    }
    for (int u0 = ua; u0 < ub; ++u0) {
      const int u = u0;
      int ne, off;
      if constexpr (SLOT) {
        const int r = pass ? (u >> 8) : (u >> 9);
        m = u & (ntile - 1); e = rt->erank[r]; nb = 0; ne = 1; off = r;
      } else {
        ne = rt->n[e]; off = rt->off[e];
      }
      unit_body(pass, u0 == ua, e, nb, m, ne, off);
      if constexpr (!SLOT) advance_unit(e, nb, m, mb, me, rt->nblk, cc, ntile);
    }
    if constexpr (TRACE) { if (tid == 0) probe[pass ? 5 : 3] = tg(); }
  }
  if (cur_pass == 0 && seg_tiles > 0) {
    __threadfence();
    bar_consumers();
    if (tid == 0) atomicAdd(cnt + C_DONE + cur_e, seg_tiles);
  }
  if constexpr (NREG) { if (cur_pass == 1) flush_norm(); }
  if constexpr(VNR)if(cur_pass==1)flush_vec_norm();

  // ---------------- grid barrier (or last-arriver election) ----------------
  __threadfence();
  bar_consumers();
  if constexpr (TRACE) { if (tid == 0) probe[6] = tg(); }
  if constexpr (LAST) {
    if (tid == 0) {
      const bool last = atomicAdd(cnt + C_BAR, 1) == G - 1;
      if (last) {
        __threadfence();
        for (int i = 0; i < NLOC; ++i) cnt[C_DONE + i] = 0;   // every CTA is past its waits
        cnt[C_ZERO] = 0;
        cnt[C_BAR] = 0;
      }
      last_cta = last;
    }
    bar_consumers();
    if (!last_cta) { dump(false); return; }
  } else {
    if (tid == 0) {
      if (atomicAdd(cnt + C_BAR, 1) == G - 1) {
        for (int i = 0; i < NLOC; ++i) cnt[C_DONE + i] = 0;   // every CTA is past its waits
        cnt[C_ZERO] = 0;
        cnt[C_BAR] = 0;
        __threadfence();
        atomicAdd(cnt + C_GEN, 1);
      } else {
        while (ld_acquire(cnt + C_GEN) == bar_gen0) __nanosleep(64);
      }
    }
    bar_consumers();
  }

  // ---------------- combine: item = (token, half of the columns) ----------------
  if constexpr (TRACE) { if (tid == 0) probe[7] = tg(); }
  for (int it = LAST ? 0 : c; it < 2 * M; it += LAST ? 1 : G) {
    const int t = it >> 1;
    const int c0 = (it & 1) * 2048 + tid * 8;
    float f[8];
    if constexpr (!ZOUT) {
      const uint4 wv = *reinterpret_cast<const uint4*>(pnw + c0);
      const __nv_bfloat16* wb = reinterpret_cast<const __nv_bfloat16*>(&wv);
#pragma unroll
      for (int k = 0; k < 8; ++k) f[k] = 1.f + __bfloat162float(wb[k]);
    }
    float scl = 0.f;
    int posl = -1;
    if constexpr (RSQ) {
      if (lane < 8) {
        posl = pos_of[t * 8 + lane];
        if (posl >= 0) scl = tw[t * 8 + lane] * rsqrtf(__ldcg(ss + posl) * (1.f / HD) + 1e-8f);
      }
    }
    float acc[8];
#pragma unroll
    for (int k = 0; k < 8; ++k) acc[k] = 0.f;
#pragma unroll
    for (int j = 0; j < 8; ++j) {
      int pos;
      float sc;
      if constexpr (RSQ) {
        pos = __shfl_sync(~0u, posl, j);
        sc = __shfl_sync(~0u, scl, j);
      } else {
        pos = pos_of[t * 8 + j];
        sc = pos >= 0 ? tw[t * 8 + j] * rsqrtf(__ldcg(ss + pos) * (1.f / HD) + 1e-8f) : 0.f;
      }
      if (pos >= 0) {
        const float4* p = reinterpret_cast<const float4*>(y + static_cast<size_t>(pos) * HD + c0);
        const float4 u0 = __ldcg(p), u1 = __ldcg(p + 1);
        if constexpr (ZOUT) {
          acc[0] += sc * u0.x; acc[1] += sc * u0.y; acc[2] += sc * u0.z; acc[3] += sc * u0.w;
          acc[4] += sc * u1.x; acc[5] += sc * u1.y; acc[6] += sc * u1.z; acc[7] += sc * u1.w;
        } else {
          acc[0] += sc * u0.x * f[0]; acc[1] += sc * u0.y * f[1]; acc[2] += sc * u0.z * f[2]; acc[3] += sc * u0.w * f[3];
          acc[4] += sc * u1.x * f[4]; acc[5] += sc * u1.y * f[5]; acc[6] += sc * u1.z * f[6]; acc[7] += sc * u1.w * f[7];
        }
      }
    }
    uint4 ov;
    __nv_bfloat16* ob = reinterpret_cast<__nv_bfloat16*>(&ov);
#pragma unroll
    for (int k = 0; k < 8; ++k) ob[k] = __float2bfloat16(acc[k]);
    *reinterpret_cast<uint4*>(out + static_cast<size_t>(t) * HD + c0) = ov;
  }
  dump(LAST || c < 2 * M);
}

size_t smem_bytes(int nt, int nstage, int M) {
  const int npairs = M * 8;
  return static_cast<size_t>(nstage) * TILE_BYTES + 2 * NCW * 32 * nt * 4 * sizeof(float) + 2 * nstage * 8 +
         sizeof(Route) + ((npairs + 15) & ~15) + 4 * npairs;
}

#define VAR_FLAGS(X) X(69) X(95) X(325)
}  // namespace

int64_t max_smem_attr() {
  int dev, optin;
  C10_CUDA_CHECK(cudaGetDevice(&dev));
  C10_CUDA_CHECK(cudaDeviceGetAttribute(&optin, cudaDevAttrMaxSharedMemoryPerBlockOptin, dev));
  int dyn = optin;
#define SET_ATTR(Fv) { cudaFuncAttributes a = {}; C10_CUDA_CHECK(cudaFuncGetAttributes(&a, moe_var<nt_of<Fv>, Fv>)); \
    C10_CUDA_CHECK(cudaFuncSetAttribute(moe_var<nt_of<Fv>, Fv>, cudaFuncAttributeMaxDynamicSharedMemorySize, optin - (int)a.sharedSizeBytes)); \
    dyn = std::min(dyn, optin - (int)a.sharedSizeBytes); }
  VAR_FLAGS(SET_ATTR)
  SET_ATTR(0)  // resident_blocks() sizes NT=1 grids with moe_var<1, 0> (same smem/threads as every NT=1 word)
#undef SET_ATTR
  return dyn;
}

int64_t smem_needed(int64_t nt, int64_t nstage, int64_t M) { return (int64_t)smem_bytes(nt, nstage, M); }
int64_t resident_blocks(int64_t nt, int64_t nstage, int64_t M) {
  int n;
  if (nt == 2) C10_CUDA_CHECK(cudaOccupancyMaxActiveBlocksPerMultiprocessor(&n, moe_var<2, NT2_PROBE>, NTHR, smem_bytes(2, nstage, M)));
  else C10_CUDA_CHECK(cudaOccupancyMaxActiveBlocksPerMultiprocessor(&n, moe_var<1, 0>, NTHR, smem_bytes(1, nstage, M)));
  return n;
}

template <int Fv>
void launch_var(std::vector<int64_t>& v, int M, int start, int stages, int grid, cudaStream_t stream) {
  cudaLaunchConfig_t cfg = {};
  cfg.gridDim = dim3(grid); cfg.blockDim = dim3(NTHR); cfg.dynamicSmemBytes = smem_bytes(nt_of<Fv>, stages, M);
  cfg.stream = stream;
  cudaLaunchAttribute attr{};
  attr.id = cudaLaunchAttributeProgrammaticStreamSerialization;
  attr.val.programmaticStreamSerializationAllowed = 1;
  if (Fv & F_PDL) { cfg.attrs = &attr; cfg.numAttrs = 1; }
  C10_CUDA_CHECK(cudaLaunchKernelEx(&cfg, moe_var<nt_of<Fv>, Fv>,
    (const __nv_bfloat16*)v[0], (const int*)v[1], (const float*)v[2], (const __nv_bfloat16*)v[3],
    (const uint8_t*)v[4], (const uint8_t*)v[5], (const float*)v[6], (const float*)v[7],
    (__nv_bfloat16*)v[8], (float*)v[9], (float*)v[10], (int*)v[11], (__nv_bfloat16*)v[12], M, start, stages,
    (uint64_t*)(v.size() > 13 ? v[13] : 0)));
}

void run(std::vector<int64_t> v, int64_t M, int64_t start, int64_t stages, int64_t grid, int64_t stream, int64_t flags) {
  if ((flags & F_SLOT) && M != 1) throw std::runtime_error("F_SLOT requires M == 1");
  if ((flags & F_TRACE) && (v.size() < 14 || !v[13])) throw std::runtime_error("F_TRACE requires a stamp buffer");
  switch (flags) {
#define CASE(Fv) case Fv: launch_var<Fv>(v, M, start, stages, grid, (cudaStream_t)stream); return;
    VAR_FLAGS(CASE)
#undef CASE
  }
  throw std::runtime_error("flag combination not instantiated");
}

std::vector<int64_t> epi_info(int64_t f,int64_t stages,int64_t M){cudaFuncAttributes a{};int r=0;int b=smem_bytes(1,stages,M);
#define INFO(F) if(f==F){C10_CUDA_CHECK(cudaFuncGetAttributes(&a,moe_var<1,F>));C10_CUDA_CHECK(cudaOccupancyMaxActiveBlocksPerMultiprocessor(&r,moe_var<1,F>,NTHR,b));}
 INFO(69) INFO(95) INFO(325)
#undef INFO
 return {r,a.numRegs,(int64_t)a.localSizeBytes,b,(int64_t)a.sharedSizeBytes};}
'
PILP_CPP = """#include <pybind11/pybind11.h>
#include <pybind11/stl.h>
#include <stdint.h>
#include <vector>
int64_t max_smem_attr();int64_t smem_needed(int64_t,int64_t,int64_t);int64_t resident_blocks(int64_t,int64_t,int64_t);
void run(std::vector<int64_t>,int64_t,int64_t,int64_t,int64_t,int64_t,int64_t);
std::vector<int64_t> epi_info(int64_t,int64_t,int64_t);
"""
PILP_FLAGS_BUILT = [69, 95, 325]
_PILP_MODULE = []


def pilp_module():
    if not _PILP_MODULE:
        tag = hashlib.sha256(PILP_CUDA.encode()).hexdigest()[:12]
        target = '-gencode=arch=compute_90a,code=sm_90a' if torch.cuda.get_device_capability() == (9, 0) else '-gencode=arch=compute_120,code=sm_120'
        mod = load_inline(name='muse_pilp_var_' + tag, cpp_sources=PILP_CPP, cuda_sources=PILP_CUDA,
            functions=['max_smem_attr', 'smem_needed', 'resident_blocks', 'run', 'epi_info'], no_implicit_headers=True,
            with_pytorch_error_handling=False, extra_cuda_cflags=['-O3', '-std=c++20', '-lineinfo', target], verbose=False)
        mod.smem_optin = mod.max_smem_attr()
        _PILP_MODULE.append(mod)
    return _PILP_MODULE[0]


def pilp_bind(state, flags_by_m):
    """Prepare-time: compile and give every flags word its own zeroed counter block (64 int32)."""
    mod = pilp_module(); dev = state['gs13'].device
    for m, flags in flags_by_m.items():
        if flags not in PILP_FLAGS_BUILT: raise ValueError(f'flags {flags} not instantiated')
        if flags & 2 and m != 1: raise ValueError('SLOT is the M=1 dispatch')
        state.setdefault('pilp_counters', {}).setdefault(flags, torch.zeros(64, device=dev, dtype=torch.int32))
    return state


def pilp_experts(data, state, flags, stages=2, grid=264, stamps=None):
    x = data['hidden_states'].contiguous(); m = x.shape[0]; p = m * 8; dev = x.device
    ids = data['topk_ids'].int().contiguous(); tw = data['topk_weights'].float().contiguous()
    mod = pilp_module()
    if mod.smem_needed(1, stages, m) > mod.smem_optin: raise ValueError('shared memory exceeds device capacity')
    grid = min(grid, state['sms'] * mod.epi_info(flags, stages, m)[0])
    bank = state['banks']['lop3']
    inter = torch.empty((p, 4096), device=dev, dtype=torch.bfloat16)
    y = torch.empty((p, 4096), device=dev); ss = torch.empty((p,), device=dev); out = torch.empty_like(x)
    tensors = [x, ids, tw, state['pnw'], bank['w13p'], bank['w2p'], state['gs13'], state['gs2'], inter, y, ss,
               state['pilp_counters'][flags], out]
    ptrs = [v.data_ptr() for v in tensors]
    if flags & 256:
        if stamps is None or stamps.shape != (grid,64):raise ValueError("epilogue trace needs [grid,64]")
        ptrs.append(stamps.data_ptr())
    mod.run(ptrs, m, data['config']['local_start'], stages, grid, torch.cuda.current_stream(dev).cuda_stream, flags)
    return out
